import{_ as t,o as i,c as s,a2 as o}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Loi Antimonopole","description":"","frontmatter":{},"headers":[],"relativePath":"fr/47-反垄断法.md","filePath":"fr/47-反垄断法.md","lastUpdated":1789183869000}'),n={name:"fr/47-反垄断法.md"};function r(a,e,l,u,d,c){return i(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="loi-antimonopole" tabindex="-1">Loi Antimonopole <a class="header-anchor" href="#loi-antimonopole" aria-label="Permalink to &quot;Loi Antimonopole&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>47</td></tr><tr><td>Module</td><td>Système Juridique et Cadre de Gouvernance</td></tr><tr><td>Mots clés</td><td>Antimonopole, Concurrence loyale, Ordre du marché symbiotique, Interdiction des comportements prédateurs, Garantie de la progression commune des Dix Mille Races</td></tr></tbody></table><h2 id="i-objectif-legislatif-et-principes-fondamentaux" tabindex="-1">I. Objectif Législatif et Principes Fondamentaux <a class="header-anchor" href="#i-objectif-legislatif-et-principes-fondamentaux" aria-label="Permalink to &quot;I. Objectif Législatif et Principes Fondamentaux&quot;">​</a></h2><p>La <em>Loi Antimonopole</em> est l&#39;une des cinq lois d&#39;accompagnement de la Civilisation Symbiotique de l&#39;Ancre. Elle vise à empêcher les comportements de monopole et de prédation dans les ressources de culture, les sectes de culture, les marchés commerciaux et autres domaines, à maintenir la concurrence loyale et l&#39;ordre du marché symbiotique de l&#39;Univers Hengyuan, et à garantir la « progression commune des Dix Mille Races » en veillant à ce qu&#39;aucune force ni organisation ne puisse s&#39;emparer des opportunités de développement par le monopole.</p><p>Cette Loi établit les principes fondamentaux suivants :</p><table tabindex="0"><thead><tr><th>Principe</th><th>Contenu</th></tr></thead><tbody><tr><td>Concurrence loyale</td><td>Tous les sujets sont en concurrence sur un pied d&#39;égalité ; l&#39;abus de position dominante et la concurrence déloyale sont interdits</td></tr><tr><td>Marché ouvert</td><td>Les accords de monopole, la division du marché et les restrictions à la concurrence excluant ou limitant la concurrence sont interdits</td></tr><tr><td>Protection des faibles</td><td>Protection penchée vers les nouveaux cultivateurs, les races débutantes et les organisations petites et moyennes</td></tr><tr><td>Ordre symbiotique</td><td>Le marché doit servir la progression commune des Dix Mille Races ; le pillage des intérêts publics par le capital et le pouvoir est interdit</td></tr><tr><td>Application unifiée</td><td>L&#39;application du droit de la concurrence est assurée par une institution unifiée ; le protectionnisme local et les comportements monopolistiques interplans sont interdits</td></tr></tbody></table><h2 id="ii-definition-du-monopole" tabindex="-1">II. Définition du Monopole <a class="header-anchor" href="#ii-definition-du-monopole" aria-label="Permalink to &quot;II. Définition du Monopole&quot;">​</a></h2><p>Cette Loi définit les actes suivants comme des actes de monopole, qui sont interdits :</p><ol><li><strong>Accords de monopole</strong> : accords entre concurrents ou entre entreprises en amont et en aval portant sur la fixation des prix, la division des marchés, la restriction de la production, le boycott, etc.</li><li><strong>Abus de position dominante</strong> : abus d&#39;une position dominante sur le marché pour vendre à des prix élevés déloyaux, vendre à perte, imposer des conditions commerciales déraisonnables, refuser de traiter, ventes liées, etc.</li><li><strong>Concentration d&#39;opérateurs</strong> : fusions, acquisitions et coentreprises qui éliminent ou restreignent la concurrence, avec déclaration préalable à l&#39;autorité antimonopole pour examen.</li><li><strong>Monopole administratif</strong> : abus du pouvoir administratif par les organes d&#39;État et les organisations publiques pour restreindre la concurrence, protectionnisme local et monopole industriel.</li><li><strong>Monopole des ressources de culture</strong> : contrôle monopolistique des ressources de culture, des nœuds d&#39;énergie spirituelle et des royaumes secrets, excluant les autres de la culture.</li><li><strong>Monopole des talents</strong> : utilisation de moyens déloyaux pour contrôler exclusivement les talents de culture, restreignant la libre circulation des talents.</li></ol><h2 id="iii-institutions-antimonopole" tabindex="-1">III. Institutions Antimonopole <a class="header-anchor" href="#iii-institutions-antimonopole" aria-label="Permalink to &quot;III. Institutions Antimonopole&quot;">​</a></h2><p>Le Tribunal Symbiotique et ses institutions d&#39;application antimonopole affiliées exercent les fonctions suivantes :</p><table tabindex="0"><thead><tr><th>Institution</th><th>Fonction</th></tr></thead><tbody><tr><td>Bureau d&#39;application antimonopole</td><td>Enquête sur les actes de monopole, ouvre des enquêtes sur les actes suspects de monopole</td></tr><tr><td>Comité d&#39;examen du monopole</td><td>Examine la concentration des opérateurs et les changements de structure du marché</td></tr><tr><td>Bureau de supervision des prix</td><td>Supervise le comportement des prix des ressources de culture et des marchandises importantes</td></tr><tr><td>Bureau de coordination interplans</td><td>Coordonne l&#39;application antimonopole entre les plans, empêchant les monopoles interplans</td></tr></tbody></table><p>L&#39;institution d&#39;application antimonopole jouit de pouvoirs d&#39;enquête : elle peut exiger des parties concernées des explications, inspecter les livres et les registres, saisir et sceller les preuves, etc. Les parties enquêtées doivent coopérer et ne doivent pas refuser ou entraver.</p><h2 id="iv-dispositions-speciales-sur-le-monopole-des-ressources-de-culture" tabindex="-1">IV. Dispositions Spéciales sur le Monopole des Ressources de Culture <a class="header-anchor" href="#iv-dispositions-speciales-sur-le-monopole-des-ressources-de-culture" aria-label="Permalink to &quot;IV. Dispositions Spéciales sur le Monopole des Ressources de Culture&quot;">​</a></h2><p>Les ressources de culture sont la richesse publique de l&#39;Univers Hengyuan ; cette Loi établit des dispositions spéciales sur leur prévention du monopole :</p><ol><li><strong>Égalité d&#39;accès aux ressources</strong> : toutes les races et tous les cultivateurs ont des droits égaux d&#39;accès aux ressources de culture ; aucune secte ni organisation ne peut occuper exclusivement les ressources centrales.</li><li><strong>Partage des nœuds d&#39;énergie spirituelle</strong> : les nœuds d&#39;énergie spirituelle clés mettent en œuvre un système de gestion partagée ; l&#39;occupation exclusive et l&#39;établissement d&#39;enclaves de culture privées sont interdits.</li><li><strong>Système ouvert des royaumes secrets</strong> : les royaumes secrets découverts par un sujet quelconque doivent être signalés à l&#39;institution de gestion et entrer dans le système des ressources publiques ; l&#39;occupation secrète est interdite.</li><li><strong>Régulation du marché des pilules</strong> : les pilules importantes et les médicaments spirituels mettent en œuvre une guidance des prix et une supervision de l&#39;approvisionnement ; l&#39;accaparement et la flambée des prix sont interdits.</li><li><strong>Supervision de la circulation des artefacts</strong> : la circulation des artefacts de haut niveau doit être enregistrée et gérée ; l&#39;établissement d&#39;un monopole des artefacts armés par le contrôle des sources d&#39;artefacts est interdit.</li></ol><h2 id="v-recours-et-responsabilite-juridique" tabindex="-1">V. Recours et Responsabilité Juridique <a class="header-anchor" href="#v-recours-et-responsabilite-juridique" aria-label="Permalink to &quot;V. Recours et Responsabilité Juridique&quot;">​</a></h2><p>Pour les actes de monopole, cette Loi prévoit les recours et responsabilités suivants :</p><ul><li><strong>Ordre de cesser</strong> : l&#39;institution d&#39;application antimonopole ordonne la cessation des actes de monopole.</li><li><strong>Amendes</strong> : des amendes sont imposées selon les gains illégaux et la gravité des circonstances.</li><li><strong>Confiscation des gains illégaux</strong> : les gains illégaux obtenus par des actes de monopole sont confisqués.</li><li><strong>Révocation des qualifications</strong> : dans les cas graves, les licences commerciales ou les qualifications des sectes de culture sont révoquées.</li><li><strong>Indemnisation des dommages</strong> : les victimes d&#39;actes de monopole ont le droit de demander une indemnisation.</li><li><strong>Responsabilité pénale</strong> : si un acte de monopole constitue une infraction pénale, la responsabilité pénale est poursuivie.</li></ul><h2 id="vi-action-d-interet-public" tabindex="-1">VI. Action d&#39;Intérêt Public <a class="header-anchor" href="#vi-action-d-interet-public" aria-label="Permalink to &quot;VI. Action d&#39;Intérêt Public&quot;">​</a></h2><p>Pour les actes de monopole qui nuisent aux intérêts publics, les sujets suivants peuvent intenter une action d&#39;intérêt public antimonopole devant le Tribunal Symbiotique :</p><ul><li>Les institutions d&#39;application antimonopole</li><li>Les organisations d&#39;intérêt public symbiotiques</li><li>D&#39;autres sujets prévus par la loi</li></ul><p>L&#39;action d&#39;intérêt public vise à faire cesser les actes de monopole, à protéger l&#39;intérêt public de l&#39;ordre du marché et à indemniser les dommages causés à l&#39;intérêt public.</p><h2 id="vii-application-de-la-loi" tabindex="-1">VII. Application de la Loi <a class="header-anchor" href="#vii-application-de-la-loi" aria-label="Permalink to &quot;VII. Application de la Loi&quot;">​</a></h2><p>Cette Loi s&#39;applique à tous les actes de monopole survenant au sein de l&#39;Univers Hengyuan, y compris les actes de monopole des sujets d&#39;autres univers relevant de la juridiction de l&#39;Univers Hengyuan. Pour les actes de monopole survenant à travers les univers, le principe de réciprocité et de consultation s&#39;applique.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La <em>Loi Antimonopole</em> est le rempart juridique de la philosophie de « progression commune des Dix Mille Races » de la Civilisation Symbiotique de l&#39;Ancre. En définissant et en punissant les actes de monopole, en établissant des institutions dédiées et en régulant le monopole des ressources de culture, elle garantit l&#39;équité et l&#39;ouverture du marché symbiotique, empêche le pillage des ressources et des opportunités de développement par toute force, et fournit des garanties institutionnelles pour la progression commune des Dix Mille Races.</p><h2 id="documents-connexes" tabindex="-1">Documents Connexes <a class="header-anchor" href="#documents-connexes" aria-label="Permalink to &quot;Documents Connexes&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitution Symbiotique : Principes Généraux)</li><li>42-消费者保护法 (Loi sur la Protection des Consommateurs)</li><li>41-共生劳动法 (Loi Symbiotique sur le Travail)</li><li>07-联产承包机制详解 (Explication Détaillée du Mécanisme de Contrat Conjoint de Production)</li></ul>',29)])])}const g=t(n,[["render",r]]);export{m as __pageData,g as default};
